function safeStoredValue(key,fallback){try{const value=localStorage.getItem(key);return value===null?fallback:value}catch{return fallback}}
function safeStoredArray(key){try{const value=JSON.parse(safeStoredValue(key,'[]'));return Array.isArray(value)?value:[]}catch{return []}}
function localDateKey(){const d=new Date();return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-')}
function dailyLessonFor(count){const d=new Date();const start=new Date(d.getFullYear(),0,0);const day=Math.floor((new Date(d.getFullYear(),d.getMonth(),d.getDate())-start)/86400000);return day%count}
function dateKeyFor(date){return [date.getFullYear(),String(date.getMonth()+1).padStart(2,'0'),String(date.getDate()).padStart(2,'0')].join('-')}


